mappings.ISO.response:
status = 200
  ? ($type(body.document) = "string" and body.document != "" and $type(body.msgId) = "string" and body.msgId != ""
      ? {"outcome": "SUCCESS", "partnerRef": body.msgId, "attributes": {"document": body.document}}
      : {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"})
: status = 404
  ? {"outcome": "NOT_FOUND", "code": "NOT_FOUND", "message": "no transfer for this EndToEndId"}
: status = 400
  ? {"outcome": "FAILED", "code": "HTTP_400", "message": "message refused by the switch"}
: {"outcome": "UNKNOWN", "reason": "UNEXPECTED_STATUS"}
